// The suite's logos (SHARED-SPEC §12): one family of marks, a monogram drawn on a 64-unit grid
// in one stroke weight, with the suite's "open" dot at the upper right. The same SVG is the
// in-app logo (shared/ui/AppLogo.tsx), the favicon and the PNGs in each app's public/brand/
// (generated by the hub's scripts/brand-assets.ts).
import type { AppId } from "../supabase/hosted";

export type MarkColors = { tile: string; glyph: string; dot: string };

/** Tile, glyph and dot colours: each app's accent (shared/design/tokens.css), in hex. */
export const MARK_COLORS: Record<AppId, MarkColors> = {
  hub: { tile: "#1d2a5c", glyph: "#fbfaf7", dot: "#c9a45c" },
  charter: { tile: "#006a6a", glyph: "#fbfaf7", dot: "#9fe0dc" },
  board: { tile: "#6042ab", glyph: "#fbfaf7", dot: "#d1c9fc" },
  ledger: { tile: "#146d34", glyph: "#fbfaf7", dot: "#b6ddbd" },
};

export const MARK_STROKE = 6.5;

/** The monogram's strokes, as SVG path data on the 64 grid. */
export const MARK_PATHS: Record<AppId, string> = {
  // H: two uprights joined at the middle (the hub between the apps)
  hub: "M21 19V45M39 19V45M21 32H39",
  // C: an open ring, the opening facing the dot
  charter: "M41.2 22.2A14 14 0 1 0 41.2 41.8",
  // B: an upright and two bowls, the lower one wider
  board: "M22 19V45M22 19H33.5A6.5 6.5 0 0 1 33.5 32H22M22 32H35.5A6.5 6.5 0 0 1 35.5 45H22",
  // L: an upright and a base
  ledger: "M24 19V45H41",
};

/** Where the dot sits (centre x, y and radius). */
export const MARK_DOT = { cx: 47, cy: 17, r: 4.25 } as const;

/** The mark as an SVG document: "tile" on its rounded tile, "glyph" alone (transparent). */
export function markSvg(
  app: AppId,
  variant: "tile" | "glyph" = "tile",
  opts: { square?: boolean } = {},
): string {
  const c = MARK_COLORS[app];
  const glyph = variant === "tile" ? c.glyph : c.tile;
  const dot = variant === "tile" ? c.dot : c.tile;
  const tile =
    variant === "tile"
      ? `<rect width="64" height="64" rx="${opts.square ? 0 : 14}" fill="${c.tile}"/>`
      : "";
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">${tile}` +
    `<path d="${MARK_PATHS[app]}" fill="none" stroke="${glyph}" stroke-width="${MARK_STROKE}" stroke-linecap="round" stroke-linejoin="round"/>` +
    `<circle cx="${MARK_DOT.cx}" cy="${MARK_DOT.cy}" r="${MARK_DOT.r}" fill="${dot}"/></svg>`
  );
}
